export const topicById=id=>topics.find(t=>t.id===id)||topics.find(t=>t.id===ATOMIC);
export function lessonEligible(l,route,tier='Higher'){return (!l.separate||route==='separate')&&(!l.higher||tier==='Higher');}
export function topicLessons(lessons,topicId,route,tier='Higher'){return lessons.filter(l=>l.topicId===topicId&&lessonEligible(l,route,tier));}
export const contextKey=s=>`${s.topicId}|${s.route}|${s.tier}`;
export function contextRun(s,type){return (type==='assessment'?s.assessments:s.reviewSessions)?.[contextKey(s)]||null;}
export function migrateTopicState(s,lessons){
 const l=lessons.find(l=>l.id===s.lessonId);s.topicId=l?.topicId||ATOMIC;s.lastLessonByTopic??={};s.lastLessonByTopic[s.topicId]=s.lessonId;
 s.assessments??={};s.reviewSessions??={};
 for(const [legacy,dictionary] of [['assessment','assessments'],['reviewSession','reviewSessions']]){const run=s[legacy];if(!run)continue;const ids=run.queue?.map(q=>lessons.find(l=>l.id===q.lessonId)?.topicId||ATOMIC)||[];if(ids.every(id=>id===ATOMIC)){const key=`${ATOMIC}|${run.route||s.route}|${run.tier||s.tier}`;if(!s[dictionary][key])s[dictionary][key]={...run,topicId:ATOMIC,route:run.route||s.route,tier:run.tier||s.tier};}delete s[legacy];}
 return s;
}

export const courses=[{id:'aqa-gcse-8464',subject:'science',code:'8464',name:'Combined Science: Trilogy',route:'combined',discipline:null},{id:'aqa-gcse-8461',subject:'science',code:'8461',name:'Biology',route:'separate',discipline:'Biology'},{id:'aqa-gcse-8462',subject:'science',code:'8462',name:'Chemistry',route:'separate',discipline:'Chemistry'},{id:'aqa-gcse-8463',subject:'science',code:'8463',name:'Physics',route:'separate',discipline:'Physics'}];
export function courseFor(s){return courses.find(c=>c.route===s.route&&(c.route==='combined'||c.discipline===topicById(s.topicId).discipline));}

export function specRefs(l,route){return (route==='combined'?(l.combinedRefs||l.refs):l.refs).map(r=>(route==='combined'?(l.topicId?.startsWith('science.biology.')?'4.':l.topicId?.startsWith('science.physics.')?'6.':'5.'):'4.')+r);}

// A route can hide an entire topic (Space Physics in Trilogy). Keep the visible
// topic and lesson coherent while retaining the hidden topic's saved progress.
export function eligibleSelection(lessons,topicId,lessonId,route,tier,lastByTopic={}){
 let candidates=topicLessons(lessons,topicId,route,tier);
 if(!candidates.length){const discipline=topics.find(t=>t.id===topicId)?.discipline,alternatives=topics.filter(t=>t.discipline===discipline);const next=alternatives.find(t=>topicLessons(lessons,t.id,route,tier).length);candidates=next?topicLessons(lessons,next.id,route,tier):lessons.filter(l=>lessonEligible(l,route,tier));}
 const remembered=lastByTopic[candidates[0]?.topicId],chosen=candidates.find(l=>l.id===lessonId)||candidates.find(l=>l.id===remembered)||candidates[0];return chosen?{topicId:chosen.topicId,lessonId:chosen.id}:{topicId,lessonId};
}
